<script setup lang="ts">
import type { RevisionPatch } from '~/types/editor'
import type { JsonValue } from '~/types/generation'
const model = defineModel<RevisionPatch>({ required: true })
defineProps<{ section: 'purpose' | 'stages' | 'materials'; disabled?: boolean; errors?: { field: string; message: string }[] }>()
function change(key: 'pedagogical_tasks'|'materials', value: JsonValue) { model.value = { ...model.value, [key]: value } as RevisionPatch }
function move(index: number, by: number) { const stages = [...model.value.stages], to = index + by; if (to < 0 || to >= stages.length) return; [stages[index],stages[to]] = [stages[to]!,stages[index]!]; model.value = {...model.value, stages: stages.map((s,i)=>({...s,order_index:i+1}))} }
</script>
<template><div class="editor-fields"><template v-if="section==='purpose'"><UiTextarea v-model="model.concept" label="Замысел мероприятия" :disabled="disabled" minlength="30" rows="5" :error="errors?.find(e=>e.field==='concept')?.message" /><UiTextarea v-model="model.pedagogical_goal" label="Педагогическая цель" :disabled="disabled" minlength="20" rows="4" :error="errors?.find(e=>e.field==='pedagogical_goal')?.message" /><RevisionFields :value="model.pedagogical_tasks" path="pedagogical_tasks" label="Воспитательные задачи" :disabled="disabled" :errors="errors" @update="change('pedagogical_tasks',$event)" /></template><template v-else-if="section==='stages'"><p class="muted">Идентификаторы этапов сохранены: связанные задания продолжают ссылаться на те же этапы.</p><article v-for="(stage,i) in model.stages" :key="String(stage.id ?? i)" class="editor-stage"><div class="editor-actions"><strong>Этап {{ i+1 }}</strong><UiButton variant="secondary" :disabled="disabled || i===0" :aria-label="`Этап ${i+1} выше`" @click="move(i,-1)">↑</UiButton><UiButton variant="secondary" :disabled="disabled || i===model.stages.length-1" :aria-label="`Этап ${i+1} ниже`" @click="move(i,1)">↓</UiButton></div><RevisionFields :value="stage" :path="`stages.${i}`" :label="`Этап ${i+1}`" :disabled="disabled" :errors="errors" @update="model.stages[i]=$event as Record<string,JsonValue>" /></article></template><RevisionFields v-else :value="model.materials" path="materials" label="Материалы" :disabled="disabled" :errors="errors" @update="change('materials',$event)" /></div></template>
